# بنك الأسئلة المركزي: أسئلة أصلية. أسئلة الرياضيات تُحسب برمجيًا (الإجابة مضمونة)،
# والبقية مكتوبة يدويًا وتمر بفحوص آلية قبل الإدخال (مراجعة معلم لم تتم بعد).
import random, json
R = random.Random(20261119)
ITEMS = []
SEEN = set()
SJ = {'ar': 'اللغة العربية', 'math': 'الرياضيات', 'en': 'اللغة الإنجليزية', 'sci': 'العلوم', 'life': 'المهارات الحياتية'}

def _add(g, s, u, l, sk, d, t, body):
    assert 1 <= g <= 6 and s in SJ and d in (1, 2, 3)
    key = (g, s, t, json.dumps(body.get('q', ''), ensure_ascii=False), json.dumps(body.get('eq', ''), ensure_ascii=False), json.dumps(body.get('o', ''), ensure_ascii=False)[:80])
    assert key not in SEEN, ('dup', body.get('q'), body.get('eq'))
    SEEN.add(key)
    assert body.get('ex'), 'no explanation'
    ITEMS.append(dict(grade=g, subj=s, unit=u, lesson=l, skill=sk, diff=d, qtype=t, body=body))

def mc(g, s, u, l, sk, d, q, right, wrong, ex, **kw):
    o = [right] + list(wrong)
    keys = [json.dumps(x, ensure_ascii=False) for x in o]
    assert len(set(keys)) == len(o), ('dup option', q)
    R.shuffle(o)
    a = o.index(right)
    _add(g, s, u, l, sk, d, 'mc', dict(q=q, o=o, a=a, ex=ex, **kw))

def tf(g, s, u, l, sk, d, q, ans, ex, **kw):
    _add(g, s, u, l, sk, d, 'tf', dict(q=q, a=bool(ans), ex=ex, **kw))

def num(g, s, u, l, sk, d, q, eq, ans, ex, **kw):
    assert isinstance(ans, int) and ans >= 0
    b = dict(q=q, a=ans, ex=ex, **kw)
    if eq: b['eq'] = eq
    _add(g, s, u, l, sk, d, 'num', b)

def fill(g, s, u, l, sk, d, q, right, wrong, ex, **kw):
    assert '__' in q
    o = [right] + list(wrong); R.shuffle(o)
    _add(g, s, u, l, sk, d, 'fill', dict(q=q, o=o, a=o.index(right), ex=ex, **kw))

def order(g, s, u, l, sk, d, q, items, ex, alt=None, **kw):
    b = dict(q=q, o=list(items), ex=ex, **kw)
    if alt: b['alt'] = alt
    _add(g, s, u, l, sk, d, 'order', b)

def match(g, s, u, l, sk, d, q, pairs, ex, **kw):
    _add(g, s, u, l, sk, d, 'match', dict(q=q, p=[list(p) for p in pairs], ex=ex, **kw))

def X(e): return '⟦' + e + '⟧'
def near(ans, k=3, lo=0, step=1):
    c = []
    for dlt in (1, -1, 2, -2, 10, -10, 3, -3):
        v = ans + dlt * step
        if v != ans and v >= lo and v not in c: c.append(v)
        if len(c) == k: break
    return c

