import re as _re
_AR = _re.compile('[\u0600-\u06FF]')
def _ltr(t):
    return '⟦' + t + '⟧' if isinstance(t, str) and t and not _AR.search(t) and '⟦' not in t else t
for _i in ITEMS:
    if _i['subj'] != 'en': continue
    b = _i['body']
    if _i['qtype'] != 'fill' and not b['q'].startswith('⟦'):
        q = b['q']
        b['q'] = _ltr(q) if not _AR.search(q) else _re.sub(r'([A-Za-z][A-Za-z0-9 ’\'?.,!-]*[A-Za-z?.!])', lambda m: '⟦' + m.group(1) + '⟧', q)
    if _i['qtype'] in ('mc',):
        b['o'] = [_ltr(o) if (' ' in o) else o for o in b['o']]
    if 'pg' in b:
        b['pg'] = dict(b['pg'], x=_ltr(b['pg']['x']))

if __name__ == '__main__':
    from collections import Counter
    print(len(ITEMS), Counter((i['grade'], i['subj']) for i in ITEMS))
    print(Counter(i['qtype'] for i in ITEMS), Counter(i['diff'] for i in ITEMS))
